    // Skip protocol if exists
    if (strstr(url, "://") != NULL) {
        start = strstr(url, "://") + 3;
    } else {
        start = url;
    }

    // Copy until we hit a slash or end of string
    int i = 0;
    while (start[i] != '\0' && start[i] != '/') {
        netloc[i] = start[i];
        i++;
    }
    netloc[i] = '\0';

    return netloc;
}

