static void
emulate_getrandom_buf (char *auth, int len)
{
     long    lowbits, highbits;

     srandom ((int)getpid() ^ time((Time_t *)0));
    highbits = random ();
     highbits = random ();
     getbits (lowbits, key->data);
     getbits (highbits, key->data + 4);
